function normalWord(t){return t.toLocaleLowerCase("es").replace(/[^\p{L}]/gu,"")}
function wordMarkup(text,idx){
 return text.split(/(\p{L}+(?:['’]\p{L}+)?)/gu).map((part,i)=>/\p{L}/u.test(part)?'<button class="word '+(WORDS[normalWord(part)]?'known':'')+'" data-word="'+esc(part)+'" data-para="'+idx+'" data-offset="'+text.split(/(\p{L}+(?:['’]\p{L}+)?)/gu).slice(0,i).join("").length+'" lang="es-ES">'+esc(part)+'</button>':esc(part)).join("");
}
function sectionFor(s,n){return [...s.sections].reverse().find(x=>x.start<=n)?.title||""}
function renderReader(){
 const s=SERMONS[sermonIndex];readerIndex=Math.min(state.bookmarks[s.id]||0,s.paragraphs.length-1);
 $("#main").innerHTML=heading("03 / LISTEN & FOLLOW","Your words.<br><em>Another way to say them.</em>","Full paragraph-aligned study renderings of both supplied sermons. Tap a word for pronunciation and contextual help; underlined words also have a glossary meaning.")+
 '<div class="toolbar"><select id="sermon" aria-label="Choose sermon">'+SERMONS.map((s,i)=>'<option value="'+i+'" '+(i===sermonIndex?'selected':'')+'>'+s.title+'</option>').join("")+'</select><span class="read-count">'+s.paragraphs.length+' sections · '+Object.keys(state.read).filter(k=>k.startsWith(s.id+":")).length+' heard</span></div>'+
 '<div class="notice">These are personal study translations and occasional natural-language adaptations of your notes, including their theological interpretations. Scripture passages are study renderings, not quotations from a named Spanish Bible edition. “Filiación” is explained as belonging to the Father; English alliteration is not forced into Spanish.</div>'+
 '<div class="reader-tools"><button class="primary" id="play-reader">▶ Read from bookmark</button><button id="pause-reader">Pause</button><button id="stop-reader">■ Stop</button><label>Jump to <select id="section-jump"><option value="">a section…</option>'+s.sections.map(x=>'<option value="'+x.start+'">'+x.title+'</option>').join("")+'</select></label><label><input type="checkbox" id="reader-english" '+(state.settings.english?'checked':'')+'> English</label><label><input type="checkbox" id="shadow" '+(shadow?'checked':'')+'> Pause after paragraph</label><label><input type="checkbox" id="loop" '+(loopParagraph?'checked':'')+'> Loop</label><button class="quiet" id="pulpit-mode">'+(readerPulpit?'Study view':'Large text')+'</button><span class="small muted" id="play-status">Bookmark: paragraph '+(readerIndex+1)+'</span></div>'+
 '<div class="reader '+(readerPulpit?'pulpit':'')+'" id="reader-body">'+s.paragraphs.map((p,i)=>'<article class="paragraph '+(i===readerIndex?'active':'')+'" id="para-'+i+'" data-index="'+i+'"><div class="para-top"><span>'+String(i+1).padStart(3,"0")+' / '+esc(sectionFor(s,i))+'</span><button data-play="'+i+'">▶ Listen here</button><button class="quiet" data-bookmark="'+i+'">Bookmark</button></div>'+(s.sections.some(x=>x.start===i)?'<h3>'+esc(sectionFor(s,i))+'</h3>':'')+'<p class="spanish" lang="es-ES">'+wordMarkup(p.es,i)+'</p><p class="english" '+(!state.settings.english?'hidden':'')+'>'+esc(p.en)+'</p></article>').join("")+'</div>';
 $("#sermon").onchange=e=>{halt();sermonIndex=+e.target.value;renderReader()};
 $("#play-reader").onclick=()=>playParagraph(readerIndex,true);
 $("#pause-reader").onclick=()=>{if(!synth)return;if(playState==="playing"){synth.pause();playState="paused"}else if(playState==="paused"){synth.resume();playState="playing"}else{toast("Start a paragraph first.")}readerStatus()};
 $("#stop-reader").onclick=halt;
 $("#reader-english").onchange=e=>{state.settings.english=e.target.checked;save();$$(".english").forEach(p=>p.hidden=!e.target.checked)};
 $("#shadow").onchange=e=>shadow=e.target.checked;$("#loop").onchange=e=>loopParagraph=e.target.checked;
 $("#pulpit-mode").onclick=()=>{readerPulpit=!readerPulpit;$("#reader-body").classList.toggle("pulpit",readerPulpit);$("#pulpit-mode").textContent=readerPulpit?"Study view":"Large text"};
 $("#section-jump").onchange=e=>{if(e.target.value==="")return;halt();readerIndex=+e.target.value;setBookmark();highlightParagraph();$("#para-"+readerIndex).scrollIntoView({behavior:"smooth",block:"start"});readerStatus()};
 $$("[data-play]").forEach(b=>b.onclick=()=>playParagraph(+b.dataset.play,true));
 $$("[data-bookmark]").forEach(b=>b.onclick=()=>{readerIndex=+b.dataset.bookmark;setBookmark();highlightParagraph();toast("Bookmark saved at paragraph "+(readerIndex+1))});
 $$("[data-word]").forEach(b=>b.onclick=()=>wordHelp(b.dataset.word,+b.dataset.para));
}
function setBookmark(){state.bookmarks[SERMONS[sermonIndex].id]=readerIndex;save()}
function highlightParagraph(){$$(".paragraph.active").forEach(x=>x.classList.remove("active"));$("#para-"+readerIndex)?.classList.add("active")}
function playParagraph(n,continuous){
 const s=SERMONS[sermonIndex];if(n>=s.paragraphs.length){halt();toast("You’ve reached the end of the sermon.");return}
 readerIndex=n;setBookmark();highlightParagraph();$("#para-"+n)?.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"instant":"smooth",block:"start"});
 speak(s.paragraphs[n].es,()=>{const key=s.id+":"+n;if(!state.read[key]){state.read[key]=true;award("read:"+key,3)}activity("read");if(loopParagraph)playParagraph(n,continuous);else{readerIndex=Math.min(n+1,s.paragraphs.length-1);setBookmark();if(continuous&&!shadow&&n+1<s.paragraphs.length)playParagraph(n+1,true);else{readerStatus();if(shadow)toast("Your turn: repeat the paragraph. Tap Read from bookmark to continue.")}}},(offset)=>{
 $$(".speaking").forEach(w=>w.classList.remove("speaking"));const words=$$("#para-"+n+" [data-word]");let w=words.find(w=>+w.dataset.offset<=offset&&+w.dataset.offset+w.dataset.word.length>offset);w?.classList.add("speaking");
 });
}
function wordHelp(word,n){const p=SERMONS[sermonIndex].paragraphs[n],key=normalWord(word);speak(word);modal('<p class="eyebrow">WORD & CONTEXT</p><h2 lang="es-ES">'+esc(word)+'</h2><p>'+esc(WORDS[key]||"This word has no standalone glossary entry yet. Use the paragraph translation below to understand its context.")+'</p>'+listenButton(word,"♫ Hear this word")+'<div class="notice"><strong>In your sermon</strong><p lang="es-ES">'+esc(p.es)+'</p><p>'+esc(p.en)+'</p></div><p class="small muted">A word can have several meanings. The English paragraph helps you choose the meaning intended here.</p>')}

const frames=[
{es:"Tenemos que",en:"We have to",ends:[["decir la verdad.","tell the truth."],["obedecer a Dios.","obey God."],["pedir perdón.","ask for forgiveness."],["seguir adelante.","keep moving forward."]]},
{es:"No tenemos que",en:"We do not have to",ends:[["tener contento a todo el mundo.","keep everyone happy."],["controlar a nuestra familia.","control our family."],["ganarnos el amor de Dios.","earn God's love."],["hacerlo todo solos.","do it all alone."]]},
{es:"Hay gracia para",en:"There is grace for",ends:[["quien necesita pedir perdón.","the one who needs to apologise."],["el cuidador agotado.","the exhausted caregiver."],["quien está aprendiendo a decir la verdad.","the one learning to tell the truth."],["el padre que debe soltar el control.","the parent who must release control."]]},
{es:"Pido a Dios que",en:"I pray to God that",ends:[["veamos su amor.","we will see his love."],["tengamos valor.","we will have courage."],["aprendamos a confiar en él.","we will learn to trust him."],["seamos fieles.","we will be faithful."]]},
{es:"Escuchad, hermanos:",en:"Listen, brothers and sisters:",ends:[["todavía hay esperanza.","there is still hope."],["Dios no ha terminado con vosotros.","God has not finished with you."],["no tengáis miedo.","do not be afraid."],["buscad primero a Dios.","seek God first."]]}
];
let frameIndex=0,endIndex=0,shadowIndex=0;
function renderVoice(){
 const f=frames[frameIndex],end=f.ends[endIndex],p=PHRASES.filter(x=>x.category==="Your voice")[shadowIndex];
 $("#main").innerHTML=heading("05 / SPEAK","Your voice.<br><em>Not a memorised script.</em>","Keep the warmth, direct questions and repetition in your notes. Build a sentence you can actually use, hear it, then make it your own.")+
 '<div class="grid two"><div class="card"><span class="tag">BUILD FROM A PATTERN</span><h2>Start with what you mean.</h2><div class="builder"><div><label for="frame">Your opening</label><select id="frame">'+frames.map((f,i)=>'<option value="'+i+'" '+(i===frameIndex?'selected':'')+'>'+f.en+'…</option>').join("")+'</select></div><div><label for="ending">Your message</label><select id="ending">'+f.ends.map((e,i)=>'<option value="'+i+'" '+(i===endIndex?'selected':'')+'>'+e[1]+'</option>').join("")+'</select></div></div><p class="builder-output" lang="es-ES">'+esc(f.es+" "+end[0])+'</p><p class="muted">'+esc(f.en+" "+end[1])+'</p>'+listenButton(f.es+" "+end[0])+' <button id="said-builder" class="secondary">I said it aloud ✓</button><div class="notice">Say it once slowly, once to one person, then once to a whole room. This is practice you self-report, not an automated pronunciation score.</div></div>'+
 '<div class="card"><span class="tag">LISTEN → REPEAT → COMPARE</span><h2>Shadow your own phrasing.</h2><p class="builder-output" lang="es-ES" style="font-size:29px">'+esc(p.es)+'</p><p>'+esc(p.en)+'</p>'+listenButton(p.es,"♫ Listen, then repeat")+' <button id="next-shadow" class="secondary">Next phrase →</button><p class="small muted" style="margin-top:17px">'+esc(p.note)+'</p><h3 style="margin-top:25px">Hear yourself.</h3><p class="small">Optional microphone recording stays in this tab. Nothing is uploaded. It is lost when you reload.</p><div class="record-tools"><button id="record">● Record my voice</button><button id="stop-record" disabled>Stop</button><audio id="record-playback" controls '+(!recordURL?'hidden':'')+' '+(recordURL?'src="'+recordURL+'"':'')+'></audio></div><p id="record-status" class="small muted" role="status">Listen for rhythm, clear vowels, and the ending of each verb.</p></div></div>'+
 '<div class="section-heading"><h2>A voice map from your notes.</h2></div><div class="grid">'+[
 ["Your address to the room","“Hear me, beloved” becomes “Escuchadme, hermanos”. Choose amados hermanos if you want a more solemn tone."],
 ["Your repeated openings","“Some of us…” → “Algunos de nosotros…”. “We need…” → “Necesitamos…”. Keep the repetition; let it build."],
 ["Your rhetorical invitations","“Can I pause right here?” → “¿Puedo hacer un inciso?”. “Can someone affirm that?” → “¿Puede alguien afirmar eso?”. Translate the purpose, not each word."],
 ["Your pastoral singular","Use tú when speaking personally to one listener: tienes, puedes, perteneces. Return to vosotros when addressing the room."],
 ["Your four points","Filiación · Percepción · Prioridad · Provisión. Explain filiación in ordinary language: tienes que saber a quién perteneces."],
 ["Your story-to-appeal transition","Tell the event: Dios lo resucitó. Then bring it home: nuestra esperanza está en un Salvador vivo."]
 ].map(([t,b])=>'<div class="card"><h3>'+t+'</h3><p>'+b+'</p></div>').join("")+'</div>';
 $("#frame").onchange=e=>{frameIndex=+e.target.value;endIndex=0;renderVoice()};
 $("#ending").onchange=e=>{endIndex=+e.target.value;renderVoice()};
 $("#said-builder").onclick=()=>{activity("speak");award("speaking",5);toast("Your voice is part of the practice. Well done for saying it aloud.")};
 $("#next-shadow").onclick=()=>{halt();shadowIndex=(shadowIndex+1)%PHRASES.filter(x=>x.category==="Your voice").length;renderVoice()};
 $("#record").onclick=startRecording;$("#stop-record").onclick=stopRecording;
}
async function startRecording(){
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast("Recording is not available in this browser. You can still repeat aloud.");return}
 try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});if(route!=="voice"){recordStream.getTracks().forEach(t=>t.stop());return}
 let chunks=[];recorder=new MediaRecorder(recordStream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};
 recorder.onstop=()=>{recordStream?.getTracks().forEach(t=>t.stop());if(recordURL)URL.revokeObjectURL(recordURL);recordURL=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));if(route==="voice"){const a=$("#record-playback");a.src=recordURL;a.hidden=false;$("#record").disabled=false;$("#stop-record").disabled=true;$("#record-status").textContent="Recording ready. Play it back and compare with the Spanish model."}activity("speak");award("speaking",5)};
 recorder.start();$("#record").disabled=true;$("#stop-record").disabled=false;$("#record-status").textContent="Recording… tap Stop when you finish.";halt();
 }catch{toast("Microphone access wasn’t available. Allow it in your browser settings, or practise aloud without recording.")}}
function stopRecording(){if(recorder?.state==="recording")recorder.stop()}
function renderLessons(){
 $("#main").innerHTML=heading("06 / CONNECT","Grammar with <em>a purpose.</em>","Start with the meaning, then learn the name. These are the structures your sermons already lean on.")+
 '<div class="grid two">'+LESSONS.map((l,i)=>'<article class="card lesson"><span class="tag">'+esc(l.level)+'</span><h2 style="font-size:27px">'+esc(l.title)+'</h2><p>'+esc(l.body)+'</p>'+l.examples.map(([es,en])=>'<div class="example"><p lang="es-ES">'+esc(es)+'</p><small>'+esc(en)+'</small><br>'+listenButton(es,"♫ Hear example")+'</div>').join("")+'<p class="practice">'+esc(l.practice)+'</p></article>').join("")+'</div><div class="section-heading"><h2>Theological language you use.</h2><a class="text-link" href="#cards" id="theology-link">Practise these cards →</a></div><div class="grid two">'+PHRASES.filter(p=>p.category==="Theology").map(p=>'<div class="card"><h3 lang="es-ES">'+esc(p.es)+'</h3><p>'+esc(p.en)+' · '+esc(p.note)+'</p>'+listenButton(p.es)+'</div>').join("")+'</div>';
 $("#theology-link").onclick=()=>{cardCategory="Theology";cardPos=0;cardRevealed=false};
}
function renderProgress(){
 const total=state.history.reduce((a,s)=>a+s.total,0),correct=state.history.reduce((a,s)=>a+s.correct,0),mastered=Object.values(state.cards).filter(c=>c.level>=3).length;
 let days=[];for(let i=13;i>=0;i--){let d=new Date();d.setDate(d.getDate()-i);let date=d.toLocaleDateString("sv-SE");days.push({date,...state.days[date]})}const max=Math.max(10,...days.map(d=>d.xp||0));
 $("#main").innerHTML=heading("YOUR PROGRESS","Dedicated <em>practice.</em>","“It’s not always natural skill, but it is always dedicated practice.” Your progress belongs to this browser. Export a backup to take it to another device.")+
 '<div class="stats"><div class="stat"><b>'+state.xp+'</b><small>XP earned</small></div><div class="stat"><b>'+(total?Math.round(correct/total*100):0)+'%</b><small>Quiz first-choice accuracy</small></div><div class="stat"><b>'+mastered+'</b><small>Familiar flashcards</small></div><div class="stat"><b>'+Object.keys(state.read).length+'</b><small>Sermon paragraphs heard</small></div></div>'+
 '<div class="grid two"><div class="card"><span class="tag">THE LAST TWO WEEKS</span><h2>Small steps count.</h2><div class="timeline">'+days.map(d=>'<div style="height:'+Math.max(3,(d.xp||0)/max*100)+'%" aria-label="'+d.date+': '+(d.xp||0)+' XP"><span>'+d.date+' · '+(d.xp||0)+' XP</span></div>').join("")+'</div><p>'+streak()+'-day practice streak · '+total+' quiz answers · '+state.history.length+' sessions</p><a href="#settings" class="text-link">Export or import progress →</a></div><div class="card"><span class="tag">YOUR NEXT OPPORTUNITY</span><h2>'+state.mistakes.length+' to revisit.</h2><p>Mistakes are saved as whole questions with their explanations. A correct answer in a later session clears the item.</p><button id="review-mistakes" class="primary">Practise my mistakes →</button></div></div>'+
 '<div class="section-heading"><h2>Recent sessions.</h2></div><div class="card">'+(state.history.length?'<div class="table-scroll"><table class="conjugations"><thead><tr><th>Date</th><th>Session</th><th>First answers</th></tr></thead><tbody>'+state.history.slice(-10).reverse().map(s=>'<tr><td>'+new Date(s.date).toLocaleDateString()+'</td><td>'+esc(s.mode)+'</td><td>'+s.correct+' / '+s.total+'</td></tr>').join("")+'</tbody></table></div>':'<p>No sessions yet. Your first ten questions are waiting in the quiz room.</p>')+'</div>';
 $("#review-mistakes").onclick=()=>{quizConfig.mode="review";startQuiz()};
}
function renderSettings(){
 const sp=voices.filter(v=>v.lang.toLowerCase()==="es-es");
 $("#main").innerHTML=heading("MAKE IT YOURS","Audio & <em>your progress.</em>","Use a Spain Spanish voice, slow the pace, and keep a backup of the practice you’ve put in.")+
 '<div class="grid two"><div class="card"><h2>Your Spanish voice.</h2><div class="setting-row"><label for="voice-select">Spain Spanish voices available on this device</label><select id="voice-select"><option value="">Automatic · Spain Spanish</option>'+sp.map(v=>'<option value="'+esc(v.voiceURI)+'" '+(state.settings.voice===v.voiceURI?'selected':'')+'>'+esc(v.name)+' · '+esc(v.lang)+'</option>').join("")+'</select></div><div class="setting-row"><label for="rate">Speaking speed</label><select id="rate">'+[.6,.7,.85,1,1.1].map(r=>'<option value="'+r+'" '+(+state.settings.rate===r?'selected':'')+'>'+r+'× '+(r===.85?'· recommended':'')+'</option>').join("")+'</select></div><div class="toolbar">'+listenButton("Escuchadme, hermanos. Todavía hay esperanza.","♫ Test Spanish audio")+'<button id="refresh-voices">Refresh voices</button><button id="stop-audio">Stop audio</button></div><p id="voice-report" class="small '+(sp.length?'muted':'accent')+'">'+(sp.length?sp.length+' Spain Spanish voice'+(sp.length===1?'':'s')+' detected.':'No es-ES voice detected yet. Refresh once; if none appears, install one below.')+'</p><div class="notice">Audio uses your browser’s speech engine, not a recording of Lindsey. Word-by-word highlighting depends on browser support; paragraph highlighting always follows playback. Some system voices need an internet connection.</div><p class="small">On iPhone / iPad: Settings → Accessibility → Spoken Content (or Read & Speak) → Voices → Spanish → Spain; download a voice, then reopen Safari. On Mac: System Settings → Accessibility → Spoken Content → System Voice → Manage Voices. Menu names vary by OS. On Windows / Android, add a Spanish (Spain) text-to-speech voice in speech or accessibility settings.</p></div>'+
 '<div class="card"><h2>Keep your progress.</h2><p>Scores, flashcard schedules and bookmarks stay in this browser’s local storage. There is no account and no automatic sync between your iPad and laptop.</p><div class="backup-row"><button id="export" class="primary">Export progress ↓</button><label class="text-link" style="cursor:pointer">Import backup<input id="import" type="file" accept=".json,application/json" hidden></label></div><p id="import-status" class="small muted" role="status"></p><div class="notice">Import replaces progress on this device. Export the current device first if you want to keep it. Audio recordings remain only in the current tab and are not included in backups.</div><p class="small muted">Progress storage: '+(storageOK?'available':'unavailable')+'. Public app and source; your practice data is not sent to a server. A system speech voice may process text using its provider.</p><a href="https://github.com/lsjordan7/pulpito-spanish" target="_blank" rel="noopener" class="text-link">Open the public GitHub repository ↗</a></div></div>';
 $("#voice-select").onchange=e=>{state.settings.voice=e.target.value;save();halt()};
 $("#rate").onchange=e=>{state.settings.rate=+e.target.value;save();halt()};
 $("#refresh-voices").onclick=()=>{voices=synth?synth.getVoices():[];renderSettings()};
 $("#stop-audio").onclick=halt;$("#export").onclick=exportProgress;
 $("#import").onchange=importProgress;
}
function exportProgress(){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:"application/json"})),a=document.createElement("a");a.href=url;a.download="pulpito-progress-"+today()+".json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Progress backup exported.")}
function validQuestion(q){return q&&typeof q.id==="string"&&typeof q.en==="string"&&typeof q.prompt==="string"&&Array.isArray(q.options)&&q.options.length>=2&&q.options.length<=6&&q.options.every(x=>typeof x==="string")&&Number.isInteger(q.answer)&&q.answer>=0&&q.answer<q.options.length&&typeof q.why==="string"}
async function importProgress(e){
 const file=e.target.files[0];if(!file)return;if(file.size>2000000){toast("This backup is too large.");return}
 try{let obj=JSON.parse(await file.text());if(obj.version!==1||!Number.isFinite(obj.xp)||obj.xp<0||!Array.isArray(obj.history)||!Array.isArray(obj.mistakes)||!obj.cards||!obj.settings||!obj.days)throw Error();
 const next=initial();next.xp=Math.floor(obj.xp);next.settings.rate=[.6,.7,.85,1,1.1].includes(+obj.settings.rate)?+obj.settings.rate:.85;next.settings.voice=typeof obj.settings.voice==="string"?obj.settings.voice:"";next.settings.english=obj.settings.english!==false;
 next.history=obj.history.filter(s=>s&&typeof s.date==="string"&&!isNaN(Date.parse(s.date))&&Number.isInteger(s.correct)&&Number.isInteger(s.total)&&s.total>0&&s.correct>=0&&s.correct<=s.total&&typeof s.mode==="string").slice(-200);
 next.mistakes=obj.mistakes.filter(validQuestion).slice(0,500);
 for(const p of PHRASES){const c=obj.cards[p.id];if(c&&Number.isInteger(c.level)&&c.level>=0&&c.level<=5&&Number.isFinite(c.due))next.cards[p.id]={level:c.level,due:c.due}}
 for(const [d,v] of Object.entries(obj.days)){if(/^\d{4}-\d{2}-\d{2}$/.test(d)&&v&&typeof v==="object"){next.days[d]={};for(const k of ["cards","quiz","read","speak","xp"])next.days[d][k]=Number.isFinite(v[k])&&v[k]>=0?Math.floor(v[k]):0}}
 for(const s of SERMONS){const n=obj.bookmarks?.[s.id];if(Number.isInteger(n)&&n>=0&&n<s.paragraphs.length)next.bookmarks[s.id]=n;for(let i=0;i<s.paragraphs.length;i++){const k=s.id+":"+i;if(obj.read?.[k]===true)next.read[k]=true}}
 for(const [k,v] of Object.entries(obj.awards||{}))if(v===true&&k.length<200&&/^\d{4}-\d{2}-\d{2}:/.test(k))next.awards[k]=true;
 modal('<h2>Replace this device’s progress?</h2><p>The selected backup contains '+next.xp+' XP and '+next.history.length+' sessions. The current device has '+state.xp+' XP.</p><button id="confirm-import" class="primary">Replace with this backup</button>');
 $("#confirm-import").onclick=()=>{state=next;save();$("#dialog").close();renderSettings();toast("Progress imported. Your practice is ready.")};
 }catch{toast("This isn’t a valid Púlpito progress backup. Your current progress is unchanged.")}
 e.target.value="";
}
go();
